                if not pl[k].endswith(('。','！','?','?','」','』','：',':','；',';','。')) and len(pl[k])>10:
                    print(f'{fn}:段起始行{start+k} (硬换行可疑): "{pl[k][-30:]}" / "{pl[k+1][:30]}"')
EOF

